404	function SpeicherKurve({ kurve, speicher, onWahl }) {
405	  const [ref, W] = useBreite(720);
406	  const [hover, setHover] = useState(null);
407	  const schmal = W < 520;
408	  const H = schmal ? 250 : 300;
409	  const P = { l: 44, r: schmal ? 14 : 22, t: 34, b: 38 };
410	  const max = SPEICHER.maxKwh;
411	  // Auf 0,1 px runden: Server und Browser rechnen Gleitkommazahlen minimal anders
412	  const x = (k) => Math.round((P.l + (k / max) * (W - P.l - P.r)) * 10) / 10;
413	  const y = (v) => Math.round((P.t + (1 - v) * (H - P.t - P.b)) * 10) / 10;
414	  const punkte = kurve.punkte;
