416	  const flaeche = `${pfad("autarkie")} L${x(max)},${y(0)} L${x(0)},${y(0)} Z`;
417	  const lohnend = punkte.filter((p) => p.kap > 0 && p.ueberschuss > 0);
418	  const opt = kurve.optimum;
419	  const aktiv = hover != null ? punkte[hover] : null;
420	  const sel = punkte[speicher];
421	
422	  const ausZeiger = (e) => {
423	    const box = e.currentTarget.getBoundingClientRect();
424	    const px = ((e.clientX - box.left) / box.width) * W;
425	    return Math.max(0, Math.min(max, Math.round(((px - P.l) / (W - P.l - P.r)) * max)));
426	  };
427	
428	  return (
429	    <div ref={ref} className="relative px-2 pb-4 md:px-3">
430	      <svg
431	        width="100%"
432	        height={H}
433	        viewBox={`0 0 ${W} ${H}`}
434	        className="block touch-pan-y select-none"
435	        role="img"
436	        aria-label={`Diagramm: Autarkie steigt von ${pct(punkte[0].autarkie)} Prozent ohne Speicher auf ${pct(punkte[max].autarkie)} Prozent bei ${max} kWh.${opt ? ` Wirtschaftliches Optimum bei ${opt.kap} kWh.` : ""}`}
437	      >
438	        <defs>
439	          <linearGradient id="ov-speicher-flaeche" x1="0" x2="0" y1="0" y2="1">
440	            <stop offset="0%" stopColor={FARBE.autarkie} stopOpacity="0.16" />
441	            <stop offset="100%" stopColor={FARBE.autarkie} stopOpacity="0" />
442	          </linearGradient>
443	        </defs>
444	
445	        {/* Wirtschaftlicher Bereich */}
446	        {lohnend.length > 0 && (
