const PFAD = "/flaeche-verpachten";
const TITEL = "Fläche für Solarpark verpachten | ÖkoInvest";
const BESCHREIBUNG =
  "Acker oder Grünland für einen Solarpark verpachten: Pachtmodelle, Vertragsinhalte, Rückbausicherheit, Steuern und der Weg bis zur ersten Pachtzahlung – kostenfrei geprüft.";

