      annahmen={[
        ["Investition vertikal", `${fmt(AGRI.capexProKwp.vertikal.mittel)} €/kWp`],
        ["Investition hoch aufgeständert", `${fmt(AGRI.capexProKwp.hoch.mittel)} €/kWp`],
